        ap(ch(0, "¿Qué clase de idea es, según Descartes?", "La idea de qué es la verdad.", "innata",
           ["innata", "adventicia", "facticia"], "Sale de la naturaleza de mi mente (AT VII 38). Locke (semana 53) va a negar que haya ideas innatas.")),
        ap(ch(0, "¿Por qué no alcanza?", "«Tengo la idea del sol porque la siento venir de afuera, contra mi voluntad: luego hay un sol afuera.»", "porque en sueños también hay ideas que vienen contra mi voluntad",
           ["porque en sueños también hay ideas que vienen contra mi voluntad", "porque el sol es una idea innata", "porque es un argumento válido"],
           "*Meditación* III (AT VII 38-39): ni la espontaneidad ni la «enseñanza de la naturaleza» prueban todavía que las ideas se parezcan a cosas.")),
